    id, enterprise_id, warehouse_id, client_operation_id, source_balance_id, target_location_id,
    target_balance_id, qty, unit, reason, actor_id, operation_id, state, version, created_at, updated_at
) VALUES (
    #{id}, #{enterpriseId}, #{warehouseId}, #{clientOperationId}, #{sourceBalanceId}, #{targetLocationId},
    #{targetBalanceId}, #{qty}, #{unit}, #{reason}, #{actorId}, #{operationId}, #{state}, 0, #{now}, #{now}
)

mapper.select:
SELECT id, source_balance_id, target_location_id, target_balance_id, qty, unit, reason, operation_id, state,
       version
FROM warehouse_move
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId}
  AND client_operation_id = #{clientOperationId}

