    id, enterprise_id, warehouse_id, client_operation_id, count_line_id, balance_id, delta_qty, reason,
    evidence_refs, actor_id, state, version, created_at, updated_at
) VALUES (
    #{id}, #{enterpriseId}, #{warehouseId}, #{clientOperationId}, #{countLineId}, #{balanceId}, #{deltaQty},
    #{reason}, CAST(#{evidenceRefs} AS JSON), #{actorId}, #{state}, 0, #{now}, #{now}
)

mapper.select:
SELECT id, count_line_id, balance_id, delta_qty, reason, decision, apply_operation_id, state, version
FROM warehouse_adjustment
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId}
  AND client_operation_id = #{clientOperationId}

SELECT id, count_line_id, balance_id, delta_qty, reason, decision, state, version, created_at
FROM warehouse_adjustment
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId}

    AND id > #{cursor}

ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE warehouse_adjustment
SET decision = #{decision}, decided_by = #{decidedBy}, decision_reason = #{decisionReason},
    state = #{state}, version = version + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId} AND id = #{adjustmentId}
  AND state = 'DRAFT' AND version = #{expectedVersion}

UPDATE warehouse_adjustment
SET apply_operation_id = #{applyOperationId}, state = 'APPLIED', version = version + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId} AND id = #{adjustmentId}
  AND state = 'APPROVED' AND version = #{expectedVersion}
